from pathlib import Path
p=Path('tests/atelier-tools.test.cjs');s=p.read_text(encoding='utf-8-sig');s+='''
test('polygonal lasso adds deliberate points and closes near the first anchor without altering artwork',()=>{let points=[];for(const p of [{x:10,y:10},{x:80,y:10},{x:80,y:80}])points=core.appendPolygonLasso(points,p,5);assert.equal(points.length,3);assert.equal(core.polygonLassoClosed(points),false);const closed=core.appendPolygonLasso(points,{x:12,y:11},5);assert.equal(core.polygonLassoClosed(closed),true);assert.equal(closed.length,4);assert.equal(points.length,3);assert.equal(core.appendPolygonLasso(closed,{x:90,y:90},5),closed);assert.equal(core.closePolygonLasso(closed),closed);assert.equal(core.polygonLassoClosed(closed.slice(0,-1)),false);assert.equal(core.closePolygonLasso(points.slice(0,2)).length,2);assert.equal(core.validRegion(closed,128,128),true);const split=core.splitOutfitPiece([{...part,locked:false,id:'dress',regions:[]}],'dress',closed,'collar','Collar',128,128);assert.equal(split.length,2);assert.equal(split[1].regions[0].erase,false);});
''';p.write_text(s,encoding='utf-8')
for f in ['docs/ATELIER.md','docs/DEVLOG.md']:
 p=Path(f);p.write_text(p.read_text(encoding='utf-8-sig')+'\nOctober 31: added Polygonal Lasso toolbar tool. Click successive anchors; the next segment follows the cursor. Click within 10 screen pixels of the first anchor or press Enter / Close selection to close. Backspace undoes a point; Escape cancels. Closing does not apply an erasure: selection remains available for Send behind body / separation / Apply selection. Existing outline and magnetic/freehand tools remain.\n',encoding='utf-8')
